    ["GetTrainerServiceDescription(1)"] = "1: string The warrior shouts, increasing the melee attack power of all party or raid members within 20 yards by 12.  Lasts 3 min.",
    ["GetTrainerServiceDescription(10)"] = "1: string Bashes the target with your shield for 6 damage.  It also interrupts spellcasting and prevents any spell in that school from being cast for 6 sec.",
    ["GetTrainerServiceDescription(100)"] = "1: string Wounds the target causing them to bleed for 147 damage over 21 sec.",
    ["GetTrainerServiceDescription(101)"] = "1: string Slam the target with your shield, causing 640 to 670 damage, increased by your Block Value, and has a 50% chance of dispelling 1 magic effect on the target. Causes a very high amount of threat.",
    ["GetTrainerServiceDescription(11)"] = "1: string Blasts nearby enemies, increasing the time between their attacks by 20% for 10 sec and doing 10 damage to them. Will affect up to 4 targets.",
    ["GetTrainerServiceDescription(12)"] = "1: string Gives a chance to parry enemy melee attacks.",
    ["GetTrainerServiceDescription(13)"] = "1: string Reduces the melee attack power of all enemies within 10 yards by 49 for 45 sec.",
    ["GetTrainerServiceDescription(14)"] = "1: string Instantly counterattack an enemy for 20 to 24 damage and a high amount of threat.   Revenge must follow a block, dodge or parry.",
    ["GetTrainerServiceDescription(15)"] = "1: string You retain up to 10 Rage when you change Stances.",
    ["GetTrainerServiceDescription(16)"] = "1: string A strong attack that increases melee damage by 32 and causes a high amount of threat.",
    ["GetTrainerServiceDescription(17)"] = "1: string A mocking attack that causes 22 damage, a moderate amount of threat and forces the target to focus attacks on you for 6 sec.",
    ["GetTrainerServiceDescription(18)"] = "1: string Increases chance to block by 75% for 7 sec, but will only block 2 attacks.",
    ["GetTrainerServiceDescription(19)"] = "1: string Disarm the enemy's weapon for 10 sec.",
    ["GetTrainerServiceDescription(2)"] = "1: string The warrior shouts, increasing the melee attack power of all party or raid members within 20 yards by 21.  Lasts 3 min.",
    ["GetTrainerServiceDescription(20)"] = "1: string Blasts nearby enemies with thunder increasing, the time between their attacks by 20% for 14 sec and doing 23 damage to them. Will affect up to 4 targets.",
    ["GetTrainerServiceDescription(21)"] = "1: string A sweeping attack that does your weapon damage plus 5 to the target and a second nearby enemy.",
    ["GetTrainerServiceDescription(22)"] = "1: string Allows one-hand and off-hand weapons to be equipped in the off-hand.",
    ["GetTrainerServiceDescription(23)"] = "1: string Wounds the target causing them to bleed for 45 damage over 15 sec.",
    ["GetTrainerServiceDescription(24)"] = "1: string Instantly counterattack any enemy that strikes you in melee for 15 sec.  Melee attacks made from behind cannot be counterattacked.  A maximum of 30 attacks will cause retaliation.",
    ["GetTrainerServiceDescription(25)"] = "1: string Slams the opponent, causing weapon damage plus 16.",
    ["GetTrainerServiceDescription(26)"] = "1: string Instantly attack the target causing 27 damage and healing you for 10% of your maximum health.  Only useable within 20 sec after you kill a non-trivial enemy.",
    ["GetTrainerServiceDescription(27)"] = "1: string The warrior shouts, increasing the melee attack power of all party or raid members within 20 yards by 33.  Lasts 3 min.",
    ["GetTrainerServiceDescription(28)"] = "1: string The warrior shouts, causing the targeted enemy to cower in fear.  Up to 5 enemies within 8 yds will flee in fear.  Lasts 8 sec.",
    ["GetTrainerServiceDescription(29)"] = "1: string Sunders the target's armor, reducing it by 180 per Sunder Armor and causes a high amount of threat.  Can be applied up to 5 times.  Lasts 30 sec.",
    ["GetTrainerServiceDescription(3)"] = "1: string Generates 10 rage at the cost of health, and then generates an additional 10 rage over 10 sec.",
    ["GetTrainerServiceDescription(30)"] = "1: string Reduces the melee attack power of all enemies within 10 yards by 77 for 45 sec.",
    ["GetTrainerServiceDescription(31)"] = "1: string Attempt to finish off a wounded foe, causing 125 damage and converting each extra point of rage into 3 additional damage.  Only usable on enemies that have 20% or less health.",
    ["GetTrainerServiceDescription(32)"] = "1: string A strong attack that increases melee damage by 44 and causes a high amount of threat.",
    ["GetTrainerServiceDescription(33)"] = "1: string Instantly counterattack an enemy for 31 to 37 damage and a high amount of threat.   Revenge must follow a block, dodge or parry.",
    ["GetTrainerServiceDescription(34)"] = "1: string Forces all nearby enemies within 10 yards to focus attacks on you for 6 sec.",
    ["GetTrainerServiceDescription(35)"] = "1: string Charge an enemy, generate 12 Rage, and Stun it for 1 sec.  Cannot be used in combat.",
    ["GetTrainerServiceDescription(36)"] = "1: string A mocking attack that causes 31 damage, a moderate amount of threat and forces the target to focus attacks on you for 6 sec.",
    ["GetTrainerServiceDescription(37)"] = "1: string Instantly overpower the enemy, causing weapon damage plus 15.  Only useable after the target dodges.  The Overpower cannot be blocked, dodged or parried.",
    ["GetTrainerServiceDescription(38)"] = "1: string Reduces the damage taken from all attacks by 60% for 12 sec.",
    ["GetTrainerServiceDescription(39)"] = "1: string Blasts nearby enemies with thunder, increasing the time between their attacks by 20% for 18 sec and doing 37 damage to them. Will affect up to 4 targets.",
    ["GetTrainerServiceDescription(4)"] = "1: string Charge an enemy, generate 9 Rage, and Stun it for 1 sec.  Cannot be used in combat.",
